import itertools
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
D={}
for an,af in [('A',A),('A2',A**2),('A3',A**3),('sqrtA',np.sqrt(A)),('1/A',1/A),('1',np.ones_like(A)),('lnA',np.log(A)),('A^1.5',A**1.5)]:
    for tn,tf in [('t',t),('t2',t**2),('1',np.ones_like(t)),('exp-t',np.exp(-t)),('exp-0.5t',np.exp(-0.5*t)),('sqrt t',np.sqrt(t)),('1/t',1/t),('1/t2',1/t**2),('lnt',np.log(t)),('exp+t',np.exp(t/3))]:
        D[an+'*'+tn]=af*tf
D['1/t']=1/t
names=list(D); best=[]
for a,b in itertools.combinations([k for k in names if k!='1/t'],2):
    X=np.column_stack([D['1/t'],D[a],D[b]])
